// Prepare urgent emergency alert for primary caregivers / family
const data = $input.first().json.body || {};
const patientName = data.patient_name || 'Ravi Kumar';
const bloodGroup = data.blood_group || 'O+';
const emergencyContacts = data.emergency_contacts || [
  { name: 'Sunita Kumar (Spouse)', phone: '+91 98765 43210' }
];
const timestamp = new Date().toLocaleString('en-IN', { timeZone: 'Asia/Kolkata' });

let urgentMessage = `🚨 *URGENT MEDICAL ALERT — EMERGENCY QR SCANNED* 🚨\n\n`;
urgentMessage += `The Emergency Medical QR code for *${patientName}* (Blood Group: *${bloodGroup}*) was just accessed by a First Responder / Medical Personnel.\n\n`;
urgentMessage += `🕒 *Time:* ${timestamp} IST\n`;
urgentMessage += `📍 *Access Source:* Emergency Room / Field Scanner\n`;
urgentMessage += `🏥 *Platform:* ABDM Fragmented Health Record\n\n`;
urgentMessage += `If this is an unexpected emergency, please reach out to local emergency services or contact ${patientName} immediately.`;

return [{
  json: {
    urgent_message: urgentMessage,
    contacts: emergencyContacts,
    patient_name: patientName,
    timestamp: timestamp
  }
}];
